A reproducer triggers a KASAN slab-use-after-free in pty_write_room()
when caif_serial's TX path calls tty_write_room(). The faulting access
is on tty->link->port.

Hold an extra kref on tty->link for the lifetime of the caif_serial line
discipline: get it in ldisc_open() and drop it in ser_release(), and
also drop it on the ldisc_open() error path.

With this change applied, the reproducer no longer triggers the UAF in
my testing.

Link: https://gist.github.com/shuangpengbai/c898debad6bdf170a84be7e6b3d8707f
Link: https://lore.kernel.org/netdev/20260301220525.1546355-1-shuangpeng.kernel@gmail.com
Fixes: e31d5a05948e ("caif: tty's are kref objects so take a reference")
Signed-off-by: Shuangpeng Bai <shuangpeng.kernel@gmail.com>
Reviewed-by: Jiayuan Chen <jiayuan.chen@linux.dev>
Link: https://patch.msgid.link/20260306034006.3395740-1-shuangpeng.kernel@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The caif_serial line discipline accesses `tty->link` (e.g., through `tty_write_room()`) during its TX path, but it only holds a reference to the `tty` itself via `tty_kref_get()`. It does not hold an additional reference to `tty->link`. When the pty master side is closed, the `tty->link` can be freed while the ldisc still holds a pointer to it, leading to a slab-use-after-free when `tty_write_room()` dereferences `tty->link->port`.

Here is the patch:

 static void ser_release(struct work_struct *work)
 {
 	struct list_head list;
 	struct ser_device *ser, *tmp;
 	struct tty_struct *tty;

 	spin_lock(&ser_lock);
 	list_replace_init(&ser_release_list, &list);
 	spin_unlock(&ser_lock);

 	if (!list_empty(&list)) {
 		rtnl_lock();
 		list_for_each_entry_safe(ser, tmp, &list, node) {
 			tty = ser->tty;
 			dev_close(ser->dev);
 			unregister_netdevice(ser->dev);
 			debugfs_deinit(ser);
+			tty_kref_put(tty->link);
 			tty_kref_put(tty);
 		}
 		rtnl_unlock();
 	}
 }


 static int ldisc_open(struct tty_struct *tty)
 {
 	struct ser_device *ser;
 	struct net_device *dev;
 	char name[64];
 	int result;

 	/* No write no play */
 	if (tty->ops->write == NULL)
 		return -EOPNOTSUPP;
 	if (!capable(CAP_SYS_ADMIN) && !capable(CAP_SYS_TTY_CONFIG))
 		return -EPERM;

 	/* release devices to avoid name collision */
 	ser_release(NULL);

 	result = snprintf(name, sizeof(name), "cf%s", tty->name);
 	if (result >= IFNAMSIZ)
 		return -EINVAL;
 	dev = alloc_netdev(sizeof(*ser), name, NET_NAME_UNKNOWN,
 			   caifdev_setup);
 	if (!dev)
 		return -ENOMEM;

 	ser = netdev_priv(dev);
 	ser->tty = tty_kref_get(tty);
+	tty_kref_get(tty->link);
 	ser->dev = dev;
 	debugfs_init(ser, tty);
 	tty->receive_room = 4096;
 	tty->disc_data = ser;
 	set_bit(TTY_DO_WRITE_WAKEUP, &tty->flags);
 	rtnl_lock();
 	result = register_netdevice(dev);
 	if (result) {
+		tty_kref_put(tty->link);
 		tty_kref_put(tty);
 		rtnl_unlock();
 		free_netdev(dev);
 		return -ENODEV;
 	}

 	spin_lock(&ser_lock);
 	list_add(&ser->node, &ser_list);
 	spin_unlock(&ser_lock);
 	rtnl_unlock();
 	netif_stop_queue(dev);
 	update_tty_status(ser);
 	return 0;
 }



